const journeyRenderBase=render;
let journeyCleanup=()=>{};
const carving=`<svg viewBox="0 0 200 460" preserveAspectRatio="none" aria-hidden="true"><defs><pattern id="wood-lines" width="28" height="180" patternUnits="userSpaceOnUse"><path d="M9 0c-8 50 12 80 0 180M20 0c10 60-12 115 0 180" fill="none" stroke="#d49a55" stroke-opacity=".15"/></pattern></defs><rect width="200" height="460" fill="url(#wood-lines)"/><path d="M19 24h162v412H19Z M30 35h140v390H30Z" fill="none" stroke="#c59151" stroke-width="2"/><path d="M42 150V95Q42 45 100 42q58 3 58 53v55ZM42 169h116v126H42ZM42 315h116v94H42Z" fill="none" stroke="#b48245" stroke-width="3"/><path d="M49 142V96q0-38 51-45 51 7 51 45v46ZM49 176h102v112H49ZM49 322h102v80H49Z" fill="none" stroke="#2d150e" stroke-width="4"/><g fill="none" stroke="#bc8a48" stroke-width="1.5"><path d="m100 70 19 27-19 27-19-27Zm0 10 11 17-11 17-11-17ZM100 197c-27 0-35 29 0 66 35-37 27-66 0-66Zm0 0v66M72 232h56M76 354q24-32 48 0-24 35-48 0Zm24-20v40"/><path d="M20 15q80 22 160 0M20 445q80-22 160 0"/></g></svg>`;
function journeyMarkup(){return `<section class="journey-intro" aria-label="A window to your sacred journey"><div class="journey-stage"><div class="journey-brand">Mahakumbh<span>Stays</span><small>NASHIK · TRIMBAKESHWAR</small></div><button class="journey-skip" onclick="skipJourney()">Skip to stays <span>↗</span></button><div class="journey-scene" role="img" aria-label="Historical view of pilgrims at Ramkund on the Godavari, Nashik"></div><div class="journey-vignette"></div><div class="journey-copy"><span>THE GODAVARI CALLS</span><h1>A window to your<br><em>sacred journey.</em></h1><p>Open a new chapter in Nashik.</p></div><div class="window-assembly" aria-hidden="true"><div class="window-crown"><span>✧</span><div></div></div><div class="window-frame"><div class="window-arch"></div><div class="window-door door-left">${carving}<i class="door-ring"></i><b class="hinge hinge-top"></b><b class="hinge hinge-bottom"></b></div><div class="window-door door-right">${carving}<i class="door-ring"></i><b class="hinge hinge-top"></b><b class="hinge hinge-bottom"></b></div></div><div class="window-sill"></div></div><div class="journey-reveal-copy"><button class="journey-play" onclick="enableJourneyMotion()">Explore the window experience →</button><span>WELCOME TO NASHIK</span><h2>Your journey begins here.</h2><p>A sacred place. A comfortable stay.</p></div><div class="journey-scroll"><span class="scroll-track"><i></i></span><span>SCROLL TO OPEN THE WINDOW</span><b>↓</b></div><span class="journey-photo-credit">Historical Ramkund photograph · Arian Zwegers / CC BY 2.0</span></div></section>`}
function skipJourney(){const next=document.querySelector('.booking-hero');if(next){next.scrollIntoView({behavior:'auto',block:'start'});const target=document.getElementById('destination');target?.focus({preventScroll:true})}}
function mountJourney(){const root=document.querySelector('.journey-intro');if(!root)return;const motion=matchMedia('(prefers-reduced-motion: reduce)');let queued=false;const update=()=>{queued=false;const range=root.offsetHeight-innerHeight;const p=Math.max(0,Math.min(1,-root.getBoundingClientRect().top/Math.max(1,range)));root.style.setProperty('--journey-progress',p);root.style.setProperty('--scene-reveal',Math.max(0,Math.min(1,(p-.52)/.28)));root.style.setProperty('--wall-opacity',1-Math.max(0,Math.min(1,(p-.52)/.28)));root.style.setProperty('--door-angle',`${Math.min(1,p/.64)*-108}deg`);root.style.setProperty('--frame-scale',1+Math.max(0,(p-.38)/.62)*2.7);root.style.setProperty('--frame-opacity',1-Math.max(0,(p-.57)/.27));root.style.setProperty('--intro-opacity',1-Math.min(1,p/.22));root.style.setProperty('--reveal-opacity',Math.min(1,Math.max(0,(p-.53)/.2)));root.style.setProperty('--scene-scale',1.12-.12*p);root.style.setProperty('--scene-light',.6+.4*p);root.classList.toggle('journey-open',p>.12)};const tick=()=>{if(!queued){queued=true;requestAnimationFrame(update)}};addEventListener('scroll',tick,{passive:true});addEventListener('resize',tick);motion.addEventListener('change',tick);update();journeyCleanup=()=>{removeEventListener('scroll',tick);removeEventListener('resize',tick);motion.removeEventListener('change',tick)}}
render=function(){journeyCleanup();journeyRenderBase();if(!location.hash||location.hash==='#/'){document.getElementById('app').insertAdjacentHTML('afterbegin',journeyMarkup());mountJourney()}};render();

function enableJourneyMotion(){document.querySelector('.journey-intro')?.classList.add('motion-enabled');dispatchEvent(new Event('resize'));window.scrollTo({top:0,behavior:'auto'})}


